(function($){"use strict";function dismissViaAjax(action,$container){if(typeof mpgr_onboarding==="undefined"){return}$.post(mpgr_onboarding.ajax_url,{action:action,nonce:mpgr_onboarding.nonce}).done(function(){if($container&&$container.length){$container.remove()}})}function initWelcomeBanner(){$(document).on("click",".mpgr-welcome-dismiss",function(e){e.preventDefault();var $banner=$(this).closest("#mpgr-welcome-banner");dismissViaAjax("mpgr_dismiss_welcome",$banner)});$(document).on("click",".mpgr-welcome-export",function(e){e.preventDefault();var $status=$("#gift_status");if($status.length){$status.val("unclaimed")}if(typeof window.mpgrExportCSV==="function"){window.mpgrExportCSV()}})}function initAdminBarPulse(){var $node=$("#wp-admin-bar-mpgr-gift-pulse");if(!$node.length||$node.find(".mpgr-dismiss-admin-bar").length){return}var $dismiss=$('<button type="button" class="mpgr-dismiss-admin-bar" aria-label="Dismiss">&times;</button>');$node.find("> .ab-item").first().append($dismiss);$dismiss.on("click",function(e){e.preventDefault();e.stopPropagation();dismissViaAjax("mpgr_dismiss_admin_bar",$node)})}$(function(){initWelcomeBanner();initAdminBarPulse()})})(jQuery);